      "id": "P7",
      "formula": "G((phase=4 & packingConfirmButton) -> (Completion_Light & X(phase=5)))",
      "explanation": "A phase-specific confirmation advances exactly one stage."
    },
    {
      "id": "P8",
      "formula": "G((phase=5 & !finishedButton) -> (Completion_Light & X(phase=5)))",
      "explanation": "Completion persists until pickup is confirmed."
    },
    {
      "id": "P9",
      "formula": "G((phase=5 & finishedButton) -> (!Completion_Light & X(phase=0)))",
      "explanation": "Pickup confirmation rearms the line."
    },
    {
      "id": "P10",
      "formula": "G((phase=1 & G((phase=1) -> F(cleaningConfirmButton)) & G((phase=2) -> F(fillingConfirmButton)) & G((phase=3) -> F(cappingConfirmButton)) & G((phase=4) -> F(packingConfirmButton))) -> F(Completion_Light))",
      "explanation": "Conditional progress: from cleaning, if every active phase eventually receives its matching confirmation, completion eventually occurs."
    },
    {
      "id": "PUB001.V2.COMPLETE",
      "formula": "G(CompleteBehaviorV2)",
      "explanation": "The complete per-invocation relation defined in specification_contract.normative_completion; requires explicit encoding before model checking."
    }
  ],
  "atomic_propositions": {
    "phase": "Ghost pre-scan state 0 idle, 1 cleaning, 2 filling, 3 capping, 4 packing, 5 complete; phase is updated once per scan.",
    "oneHotOutputs": "At most one of Pump_Motor, Filling_Valve, Capping_Machine, Packing_Machine, Completion_Light is TRUE.",
    "init": "Before the first scan, phase=0 and all outputs FALSE.",
    "all variable names": "The identically named sampled input or end-of-scan output in interface.",
    "CompleteBehaviorV2": "\u72ec\u7acb\u5b9a\u4e49nextPhase\uff1a0\u6709\u74f6\u21921\uff0c\u5426\u52190\uff1b1\u6e05\u6d17\u786e\u8ba4\u21922\uff0c\u5426\u52191\uff1b2\u704c\u88c5\u786e\u8ba4\u21923\uff0c\u5426\u52192\uff1b3\u65cb\u76d6\u786e\u8ba4\u21924\uff0c\u5426\u52193\uff1b4\u5305\u88c5\u786e\u8ba4\u21925\uff0c\u5426\u52194\uff1b5\u53d6\u74f6\u786e\u8ba4\u21920\uff0c\u5426\u52195\u3002\u6bcf\u62cd\u53ea\u7528\u65e7phase\u9009\u62e9\u4e00\u4e2a\u5206\u652f\u3002\u8865G(X(phase)=nextPhase)\uff0c\u5e76\u9010\u4e00\u89c4\u5b9aPump_Motor\u2194nextPhase=1\u3001Filling_Valve\u21942\u3001Capping_Machine\u21943\u3001Packing_Machine\u21944\u3001Completion_Light\u21945\uff1b\u5176\u4f59\u5168\u90e8\u4e3a\u5047\u3002\u521d\u59cbphase=0\u4f5c\u4e3a\u72ec\u7acb\u521d\u503c\u6761\u4ef6\u3002"
  }
}

