    "body": "// Standard IEC TON timer block declaration, invocation, and reading Q/ET\nVAR\n    timer : TON;\nEND_VAR\ntimer(IN := runCondition, PT := T#2s);\nIF timer.Q THEN\n    // Timer expired; timer.ET holds elapsed time\nEND_IF;\nIF NOT runCondition THEN\n    timer(IN := FALSE); // Reset timer\nEND_IF;"
  },
